  /* ------------------------------------------------------------------
    CONFIG — change these three lines and nothing else, normally.
    FIELD_NAME must match the property name on your form model.
 ------------------------------------------------------------------ */
 const FIELD_NAME  = 'allergies';
 const FIELD_LABEL = 'Known allergies';
 const FIELD_HINT  = 'Start typing to search; add free-text if not listed';

 const OPTIONS = [
   'Penicillin', 'Amoxicillin', 'Cephalosporins', 'Sulfonamides', 'Aspirin',
   'Ibuprofen', 'Codeine', 'Morphine', 'Iodine contrast media', 'Latex',
   'Peanuts', 'Tree nuts', 'Shellfish', 'Eggs', "Cow's milk", 'Soya',
   'Wheat / gluten', 'Sesame', 'Bee sting', 'Wasp sting', 'Dust mite',
   'Pollen', 'Animal dander', 'Chlorhexidine', 'Adhesive tape / plaster'
 ];

 const ALLOW_FREE_TEXT = true;
 const READ_ONLY = form?.formMode === 'readonly';

 /* ------------------------------------------------------------------
    STYLES — injected once per page, keyed by id so re-renders are cheap.
 ------------------------------------------------------------------ */
 const STYLE_ID = 'chipfield-styles';

 const injectStyles = () => {
   if (document.getElementById(STYLE_ID)) return;
   const el = document.createElement('style');
   el.id = STYLE_ID;
   el.textContent = `
     .chipfield { --cf-border:#d9dce1; --cf-border-focus:#6b7b8f; --cf-text:#1f2429;
       --cf-muted:#7c848d; --cf-placeholder:#9aa1a9; --cf-chip-bg:#fdeaef;
       --cf-chip-text:#c22a4e; --cf-chip-border:#f6ccd7; --cf-radius:8px;
       font-family:inherit; color:var(--cf-text); }
     .chipfield__label { display:block; font-size:13px; font-weight:700; margin-bottom:8px; }
     .chipfield__control { position:relative; }
     .chipfield__box { display:flex; flex-wrap:wrap; align-items:center; gap:6px;
       min-height:42px; padding:6px 10px; background:#fff; border:1px dashed var(--cf-border);
       border-radius:var(--cf-radius); cursor:text; transition:border-color .15s, box-shadow .15s; }
     .chipfield__box:hover { border-color:#c3c8cf; }
     .chipfield--focused .chipfield__box { border-style:solid; border-color:var(--cf-border-focus);
       box-shadow:0 0 0 3px rgba(107,123,143,.14); }
     .chipfield--readonly .chipfield__box { background:#f7f8f9; cursor:default; border-style:solid; }
     .chipfield__chip { display:inline-flex; align-items:center; gap:6px; padding:4px 6px 4px 10px;
       background:var(--cf-chip-bg); color:var(--cf-chip-text); border:1px solid transparent;
       border-radius:999px; font-size:11.5px; font-weight:600; letter-spacing:.04em;
       text-transform:uppercase; white-space:nowrap; max-width:100%; }
     .chipfield__chip-text { overflow:hidden; text-overflow:ellipsis; }
     .chipfield__chip--freetext { border-style:dashed; border-color:var(--cf-chip-border); background:transparent; }
     .chipfield__chip--armed { box-shadow:0 0 0 2px rgba(194,42,78,.35); }
     .chipfield__remove { all:unset; display:grid; place-items:center; width:16px; height:16px;
       border-radius:50%; cursor:pointer; font-size:13px; line-height:1; color:inherit; opacity:.65; }
     .chipfield__remove:hover { opacity:1; background:#fbdae3; }
     .chipfield__remove:focus-visible { opacity:1; outline:2px solid var(--cf-chip-text); outline-offset:1px; }
     .chipfield__input { flex:1 1 140px; min-width:120px; border:0; outline:0; padding:5px 2px;
       font:inherit; font-size:13.5px; color:var(--cf-text); background:transparent; }
     .chipfield__input::placeholder { color:var(--cf-placeholder); }
     .chipfield__hint { font-size:12px; color:var(--cf-muted); margin-top:7px; }
     .chipfield__menu { position:absolute; z-index:1050; top:calc(100% + 4px); left:0; right:0;
       max-height:232px; overflow-y:auto; padding:4px; background:#fff; border:1px solid var(--cf-border);
       border-radius:var(--cf-radius); box-shadow:0 6px 24px rgba(20,26,33,.12),0 1px 3px rgba(20,26,33,.08);
       list-style:none; margin:0; }
     .chipfield__menu[hidden] { display:none; }
     .chipfield__option { display:flex; align-items:center; justify-content:space-between; gap:12px;
       padding:8px 10px; border-radius:5px; font-size:13.5px; cursor:pointer; }
     .chipfield__option[aria-selected="true"] { background:#f2f5f8; }
     .chipfield__option mark { background:transparent; color:var(--cf-chip-text); font-weight:700; }
     .chipfield__option-tag { font-size:10.5px; letter-spacing:.05em; text-transform:uppercase;
       color:var(--cf-muted); flex:none; }
     .chipfield__option--create { color:var(--cf-muted); }
     .chipfield__option--create strong { color:var(--cf-text); }
     .chipfield__empty { padding:10px; font-size:13px; color:var(--cf-muted); }
     .chipfield__sr { position:absolute; width:1px; height:1px; padding:0; margin:-1px;
       overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap; border:0; }
     @media (prefers-reduced-motion: reduce) { .chipfield * { transition:none !important; } }
   `;
   document.head.appendChild(el);
 };

 /* ------------------------------------------------------------------
    WIDGET — plain DOM, no React state. Instance is parked on the node
    so React re-renders don't rebuild or reset it.
 ------------------------------------------------------------------ */
 const buildChipField = (host, config) => {
   const esc = (s) => String(s).replace(/[&<>"']/g, (c) =>
     ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

   const uid = 'cf-' + Math.random().toString(36).slice(2, 8);
   const state = { values: [], activeIndex: -1, armed: false, createIndex: -1 };

   host.innerHTML = `
     <div class="chipfield${config.readOnly ? ' chipfield--readonly' : ''}">
       <label class="chipfield__label" for="${uid}-input">${esc(config.label)}</label>
       <div class="chipfield__control">
         <div class="chipfield__box" data-box>
           <input class="chipfield__input" id="${uid}-input" type="text" autocomplete="off"
             spellcheck="false" role="combobox" aria-expanded="false"
             aria-controls="${uid}-menu" aria-autocomplete="list"
             placeholder="${esc(config.placeholder)}" ${config.readOnly ? 'disabled' : ''}>
         </div>
         <ul class="chipfield__menu" id="${uid}-menu" role="listbox" hidden></ul>
       </div>
       ${config.hint ? `<div class="chipfield__hint">${esc(config.hint)}</div>` : ''}
       <div class="chipfield__sr" aria-live="polite" data-live></div>
     </div>`;

   const root  = host.querySelector('.chipfield');
   const box   = host.querySelector('[data-box]');
   const input = host.querySelector('.chipfield__input');
   const menu  = host.querySelector('.chipfield__menu');
   const live  = host.querySelector('[data-live]');

   const has = (label) =>
     state.values.some((v) => v.label.toLowerCase() === String(label).trim().toLowerCase());

   const emit = () => config.onChange(state.values.map((v) => ({ ...v })));

   const paintChips = () => {
     box.querySelectorAll('.chipfield__chip').forEach((n) => n.remove());
     state.values.forEach((v, i) => {
       const chip = document.createElement('span');
       chip.className = 'chipfield__chip'
         + (v.freeText ? ' chipfield__chip--freetext' : '')
         + (state.armed && i === state.values.length - 1 ? ' chipfield__chip--armed' : '');
       if (v.freeText) chip.title = `${v.label} — free text, not on the reference list`;
       chip.innerHTML = `<span class="chipfield__chip-text">${esc(v.label)}</span>`
         + (config.readOnly ? ''
           : `<button type="button" class="chipfield__remove" aria-label="Remove ${esc(v.label)}">&times;</button>`);
       const btn = chip.querySelector('button');
       if (btn) btn.addEventListener('click', () => { remove(i); input.focus(); });
       box.insertBefore(chip, input);
     });
     input.placeholder = state.values.length ? config.placeholder : config.emptyPlaceholder;
     if (config.readOnly) input.placeholder = state.values.length ? '' : '—';
   };

   const add = (label, silent) => {
     const clean = String(label || '').trim().replace(/\s+/g, ' ');
     if (!clean || has(clean)) return false;
     const canonical = config.options.find((o) => o.toLowerCase() === clean.toLowerCase());
     state.values.push({ label: canonical || clean, freeText: !canonical });
     input.value = '';
     paintChips();
     if (!silent) { live.textContent = `${canonical || clean} added`; emit(); }
     return true;
   };

   const remove = (index) => {
     const [gone] = state.values.splice(index, 1);
     paintChips();
     if (gone) { live.textContent = `${gone.label} removed`; emit(); }
   };

   const highlight = (label, q) => {
     if (!q) return esc(label);
     const i = label.toLowerCase().indexOf(q);
     if (i < 0) return esc(label);
     return esc(label.slice(0, i)) + '<mark>' + esc(label.slice(i, i + q.length))
       + '</mark>' + esc(label.slice(i + q.length));
   };

   const setActive = (i) => {
     state.activeIndex = i;
     Array.from(menu.children).forEach((li, n) => li.setAttribute('aria-selected', String(n === i)));
     const el = menu.children[i];
     if (!el) return;
     input.setAttribute('aria-activedescendant', el.id);
     const top = el.offsetTop, bottom = top + el.offsetHeight;
     if (top < menu.scrollTop) menu.scrollTop = top;
     else if (bottom > menu.scrollTop + menu.clientHeight) menu.scrollTop = bottom - menu.clientHeight;
   };

   const closeMenu = () => {
     menu.hidden = true;
     input.setAttribute('aria-expanded', 'false');
     input.removeAttribute('aria-activedescendant');
     state.activeIndex = -1;
   };

   const openMenu = () => {
     if (config.readOnly) return;
     const q = input.value.trim().toLowerCase();
     const matches = config.options
       .filter((o) => !has(o))
       .filter((o) => !q || o.toLowerCase().includes(q))
       .slice(0, 50);

     const canCreate = config.allowFreeText && q && !has(q)
       && !config.options.some((o) => o.toLowerCase() === q);

     if (!matches.length && !canCreate) {
       menu.innerHTML = `<li class="chipfield__empty">No matches.${
         config.allowFreeText ? ' Keep typing to add it as free text.' : ''}</li>`;
       menu.hidden = false;
       input.setAttribute('aria-expanded', 'true');
       state.activeIndex = -1;
       return;
     }

     menu.innerHTML = '';
     matches.forEach((label, i) => {
       const li = document.createElement('li');
       li.className = 'chipfield__option';
       li.id = `${uid}-opt-${i}`;
       li.setAttribute('role', 'option');
       li.setAttribute('aria-selected', 'false');
       li.innerHTML = `<span>${highlight(label, q)}</span>`;
       li.addEventListener('click', () => { add(label); input.focus(); openMenu(); });
       li.addEventListener('mousemove', () => setActive(i));
       menu.appendChild(li);
     });

     if (canCreate) {
       const i = matches.length;
       const li = document.createElement('li');
       li.className = 'chipfield__option chipfield__option--create';
       li.id = `${uid}-opt-${i}`;
       li.setAttribute('role', 'option');
       li.setAttribute('aria-selected', 'false');
       li.innerHTML = `<span>Add <strong>${esc(input.value.trim())}</strong></span>`
         + `<span class="chipfield__option-tag">free text</span>`;
       li.addEventListener('click', () => { add(input.value); input.focus(); openMenu(); });
       li.addEventListener('mousemove', () => setActive(i));
       menu.appendChild(li);
       state.createIndex = i;
     } else {
       state.createIndex = -1;
     }

     menu.hidden = false;
     input.setAttribute('aria-expanded', 'true');
     setActive(menu.children.length ? 0 : -1);
   };

   const commitActive = () => {
     const el = menu.children[state.activeIndex];
     if (!el || el.classList.contains('chipfield__empty')) return false;
     el.click();
     return true;
   };

   /* --- listeners --- */
   box.addEventListener('mousedown', (e) => {
     if (e.target === box && !config.readOnly) { e.preventDefault(); input.focus(); }
   });
   input.addEventListener('input', () => { state.armed = false; paintChips(); openMenu(); });
   input.addEventListener('focus', () => { root.classList.add('chipfield--focused'); openMenu(); });
   input.addEventListener('blur', () => {
     root.classList.remove('chipfield--focused');
     state.armed = false;
     paintChips();
     setTimeout(closeMenu, 120);
   });
   menu.addEventListener('mousedown', (e) => e.preventDefault());

   input.addEventListener('keydown', (e) => {
     const open = !menu.hidden;
     if (e.key === 'ArrowDown') {
       e.preventDefault();
       if (!open) return openMenu();
       setActive((state.activeIndex + 1) % menu.children.length);
     } else if (e.key === 'ArrowUp') {
       e.preventDefault();
       if (!open) return;
       setActive((state.activeIndex - 1 + menu.children.length) % menu.children.length);
     } else if (e.key === 'Enter' || e.key === ',') {
       if (e.key === ',' && !input.value.trim()) return;
       e.preventDefault();
       e.stopPropagation();              // don't let Enter submit the host form
       if (open && commitActive()) { openMenu(); return; }
       if (config.allowFreeText) { add(input.value); openMenu(); }
     } else if (e.key === 'Escape') {
       if (open) { e.preventDefault(); e.stopPropagation(); closeMenu(); }
     } else if (e.key === 'Backspace') {
       if (input.value === '' && state.values.length) {
         e.preventDefault();
         if (state.armed) { state.armed = false; remove(state.values.length - 1); }
         else { state.armed = true; paintChips(); }
       }
     } else if (e.key === 'Tab') {
       closeMenu();
     }
   });

   paintChips();

   return {
     setValues: (list) => {
       state.values = [];
       (list || []).forEach((v) => add(typeof v === 'string' ? v : v?.label, true));
       paintChips();
     },
     getValues: () => state.values.map((v) => ({ ...v })),
     destroy: () => { host.innerHTML = ''; }
   };
 };

 /* ------------------------------------------------------------------
    MOUNT — no ref. This JSX is parsed rather than compiled, so a
    function ref gets coerced to a string and React rejects it. Instead
    the container carries a stable id and we adopt it once it lands in
    the DOM. Mounting is idempotent: the instance is parked on the node,
    so re-renders find it already built and leave it alone.
 ------------------------------------------------------------------ */
 const HOST_ID = 'chipfield-host-' + FIELD_NAME;

 const mount = (node) => {
   if (!node || node.__chipfield) return;
   injectStyles();

   const initial = data?.[FIELD_NAME];

   node.__chipfield = buildChipField(node, {
     label: FIELD_LABEL,
     hint: FIELD_HINT,
     placeholder: 'Type to add another…',
     emptyPlaceholder: 'Type to add an allergy…',
     options: OPTIONS,
     allowFreeText: ALLOW_FREE_TEXT,
     readOnly: READ_ONLY,
     onChange: (values) => {
       // write back to the form model so it saves with the rest of the form
       form?.setFieldsValue?.({ [FIELD_NAME]: values.map((v) => v.label) });

       // optional: expose to other components on the page
       setGlobalState?.({
         key: FIELD_NAME,
         data: { values: values.map((v) => v.label), detailed: values }
       });
     }
   });

   node.__chipfield.setValues(Array.isArray(initial) ? initial : []);
 };

 // The container doesn't exist yet on first render, so poll for it across a
 // few frames. Every re-render calls this again, which self-heals if the host
 // ever throws the node away and builds a fresh one.
 const adoptHost = (attempt) => {
   const node = document.getElementById(HOST_ID);
   if (node) { mount(node); return; }
   if (attempt < 60 && typeof requestAnimationFrame === 'function') {
     requestAnimationFrame(() => adoptHost(attempt + 1));
   }
 };

 injectStyles();
 adoptHost(0);

 return `<div id=${HOST_ID}></div>`;

